"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/cards/variants/05-story";
export interface ArtemisStoryCardProps {
  className?: string;
}
export function ArtemisStoryCard({ className }: ArtemisStoryCardProps) {
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <Variant0 />
    </ArtemisScope>
  );
}

"use client";
// @zeus-internal
import { motion, useInView, useReducedMotion } from "motion/react";
import { useRef, useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL } from "../../../lib/ease";
export default function CardsStory() {
    const root = useRef<HTMLElement>(null);
    const inView = useInView(root, { once: true, amount: 0.2 });
    const reduce = useReducedMotion();
    const [hovered, setHovered] = useState(false);
    return (<>
      <>
        <motion.article ref={root} initial={{ opacity: 0, y: 14 }} animate={inView ? { opacity: 1, y: 0 } : { opacity: 0, y: 14 }} transition={reduce ? { duration: 0 } : { duration: 0.5, ease: ARTEMIS_EASE_OUT }} onHoverStart={() => setHovered(true)} onHoverEnd={() => setHovered(false)} className="art:relative art:w-full art:max-w-md art:rounded-3xl art:border art:border-border art:bg-background art:p-4 art:@min-[640px]/artemis:rounded-3xl art:@min-[640px]/artemis:p-6">
          <div className="art:flex art:items-center art:justify-between art:gap-4 art:px-1 art:@min-[640px]/artemis:px-2">
            <span className="art:inline-flex art:h-8 art:items-center art:rounded-lg art:bg-primary art:px-3 art:font-medium art:text-xs art:text-primary-foreground">
              {"Field notes"}
            </span>
            <div className="art:flex art:h-8 art:overflow-hidden art:rounded-lg art:border art:border-border art:bg-primary art:font-medium art:text-xs">
              <span className="art:grid art:min-w-11 art:place-items-center art:px-2.5 art:text-primary-foreground">
                {"SEP"}
              </span>
              <span className="art:grid art:min-w-10 art:place-items-center art:rounded-lg art:bg-background art:px-2.5 art:text-foreground">
                {"04"}
              </span>
            </div>
          </div>
          <div className="art:px-1 art:pt-8 art:pb-7 art:@min-[640px]/artemis:px-2 art:@min-[640px]/artemis:pt-10 art:@min-[640px]/artemis:pb-8">
            <h2 className="art:text-balance art:text-foreground art:leading-[1.05] art:tracking-[-0.04em] art:text-4xl art:font-medium">
              {"Discovering quiet"}
            </h2>
            <p className="art:mt-4 art:max-w-[36ch] art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base art:@min-[640px]/artemis:leading-7">
              {"Beyond the city, green ridgelines stretch into the horizon under a veil of morning mist."}
            </p>
          </div>
          <div className="art:relative art:aspect-[4/3] art:overflow-hidden art:rounded-3xl art:border art:border-border art:@min-[640px]/artemis:rounded-3xl">
            <motion.div animate={{ scale: hovered && !reduce ? 1.035 : 1 }} transition={ARTEMIS_SPRING_PANEL} className="art:absolute art:-inset-1">
              <img src="/assets/artemis/48ec124ce0933be4634d.avif" alt="Green mountain ridges beneath a cloudy sky" className="art:size-full art:object-cover"/>
            </motion.div>
            <div aria-hidden="true" className="art:absolute art:inset-x-0 art:bottom-0 art:h-2/5 art:bg-gradient-to-t art:from-background/50 art:to-transparent"/>
            <div className="art:absolute art:bottom-4 art:left-4 art:flex art:max-w-[75%] art:items-start art:gap-2 art:rounded-2xl art:border art:border-border art:bg-background/80 art:px-3 art:py-2.5 art:text-foreground art:backdrop-blur-md art:@min-[640px]/artemis:bottom-5 art:@min-[640px]/artemis:left-5">
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-map-pin art:mt-0.5 art:size-4 art:shrink-0" aria-hidden="true">
                <path d="M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0"/>
                <circle cx="12" cy="10" r="3"/>
              </svg>
              <div className="art:min-w-0">
                <p className="art:truncate art:font-medium art:text-sm">
                  {"Pine Ridge"}
                </p>
                <p className="art:mt-0.5 art:truncate art:text-muted-foreground art:text-xs">
                  {"Virginia, USA"}
                </p>
              </div>
            </div>
          </div>
        </motion.article>
      </>
    </>);
}
